settings.liquid:
{% style %}
.timeline-wrapper {
  margin: 1.5rem 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

.timeline-track {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  position: relative;
  margin-bottom: 1rem;
}

.timeline-track::before {
  content: '';
  position: absolute;
  top: 20px;
  left: calc(16.67% + 20px);
  right: calc(16.67% + 20px);
  height: 2px;
  background: #e5e7eb;
  z-index: 1;
}

.timeline-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  z-index: 2;
}

.timeline-indicator {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #e5e7eb;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.5rem;
}

.timeline-indicator.active {
  background: #22c55e;
}

.timeline-indicator svg {
  width: 20px;
  height: 20px;
}

.timeline-indicator.active svg {
  stroke: white;
}

.timeline-indicator svg {
  stroke: #6b7280;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.timeline-text {
  font-size: 0.875rem;
  text-align: center;
  margin: 0;
  color: #6b7280;
}

.timeline-text.active {
  color: #16a34a;
  font-weight: 500;
}

.timeline-delivery {
  text-align: right;
  font-size: 0.875rem;
  color: #4b5563;
  margin: 0.5rem 0 0;
}

@media (max-width: 640px) {
  .timeline-text {
    font-size: 0.75rem;
  }

  .timeline-track::before {
    left: calc(16.67% + 15px);
    right: calc(16.67% + 15px);
  }

  .timeline-indicator {
    width: 32px;
    height: 32px;
  }

  .timeline-indicator svg {
    width: 16px;
    height: 16px;
  }

  .timeline-delivery {
    text-align: center;
  }
}
{% endstyle %}

<div class="timeline-wrapper">
  <div class="timeline-track">
    <!-- Step 1: Parts in stock -->
    <div class="timeline-step">
      <div class="timeline-indicator active">
        <svg viewBox="0 0 24 24">
          <path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/>
          <polyline points="3.27 6.96 12 12.01 20.73 6.96"/>
          <line x1="12" y1="22.08" x2="12" y2="12"/>
        </svg>
      </div>
      <p class="timeline-text active">Pièces en stock</p>
    </div>

    <!-- Step 2: Workshop Assembly -->
    <div class="timeline-step">
      <div class="timeline-indicator">
        <svg viewBox="0 0 24 24">
          <circle cx="12" cy="12" r="10"/>
          <polyline points="12 6 12 12 16 14"/>
        </svg>
      </div>
      <p class="timeline-text">Assemblage</p>
    </div>

    <!-- Step 3: Delivery -->
    <div class="timeline-step">
      <div class="timeline-indicator">
        <svg viewBox="0 0 24 24">
          <path d="M3 3h18v13H3z"/>
          <path d="M16 8h4l3 3v5h-7V8z"/>
          <circle cx="7.5" cy="18.5" r="2.5"/>
          <circle cx="18.5" cy="18.5" r="2.5"/>
        </svg>
      </div>
      <p class="timeline-text">Livraison</p>
    </div>
  </div>

  <p class="timeline-delivery">
    Délai de livraison éstimé: <strong>{% assign future_date = 'now' | date: '%s' | plus: 864000 %}{{ future_date | date: '%d' }} {% assign month = future_date | date: '%m' %}{% case month %}{% when '01' %}Janvier{% when '02' %}Février{% when '03' %}Mars{% when '04' %}Avril{% when '05' %}Mai{% when '06' %}Juin{% when '07' %}Juillet{% when '08' %}Août{% when '09' %}Septembre{% when '10' %}Octobre{% when '11' %}Novembre{% when '12' %}Décembre{% endcase %} {{ future_date | date: '%Y' }}</strong>
  </p>
</div>
